def values(self, *keys):
    """ Return the values of the record, optionally filtering to include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included
    :return: list of values
    :rtype: list
    """

    if not keys:
        return list(self.values())

    return [self[key] for key in keys]

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary, optionally including only certain values by index or key. Keys provided in the items that are not in the record will be inserted with a value of :const:`None`; indexes provided that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Check if any keys are provided
    if keys:
        # Initialize an empty dictionary to store the values
        values = {}

        # Iterate over the provided keys
        for key in keys:
            # Check if the key is an index
            if isinstance(key, int):
                # Check if the index is out of bounds
                if key >= len(self.items):
                    raise IndexError(f"Index {key} is out of bounds")

                # Insert the value at the specified index into the dictionary
                values[key] = self.items[key]

            # Check if the key is a key
            elif isinstance(key, str):
                # Check if the key is present in the record
                if key not in self.keys:
                    raise KeyError(f"Key {key} is not present in the record")

                # Insert the value at the specified key into the dictionary
                values[key] = self.keys[key]

            # Raise a TypeError if the key is invalid
            else:
                raise TypeError(f"Key {key} has an invalid type. Only integers and strings are supported.")

        # Return the dictionary of values
        return values

    # If no keys are provided, return all the values
    else:
        # Return a dictionary of all the values, keyed by field name
        return {key: value for key, value in self.items.items()}

