def parse_version(s: str) -> tuple[int, ...]:
    # Split the version string on periods and convert each component to an integer
    components = (int(x) for x in s.split("."))

    # Check if the version is in the format of x.y.z, where x, y, and z are integers
    if len(components) != 3:
        raise ValueError(f"Invalid version string: {s}")

    # Return the version as a tuple of integers
    return tuple(components)
