def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorate(func):
        def _clear():
            nonlocal _partial_ordered_dict, _remove_old
            _partial_ordered_dict = partial_ordered_dict(maxsize, default_value=_remove_old)
            _remove_old = functools.partial(_remove_old, lock=_lock)

        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            k = (args, frozenset(kwargs.items()))
            v = None
            with _lock:
                if k in _partial_ordered_dict:
                    v = _partial_ordered_dict[k]
                else:
                    v = func(*args, **kwargs)
                    _partial_ordered_dict[k] = v
            if v is not None:
                return v

        def cache_info():
            return _partial_ordered_dict.cache_info()

        def cache_clear():
            _cache_clear()

        def lru_root():
            return min(_partial_ordered_dict.keys(), key=_partial_ordered_dict.peek)

        def empty():
            return len(_partial_ordered_dict) == 0

        wrapped.cache_info = cache_info
        wrapped.cache_clear = cache_clear
        wrapped.lru_root = lru_root
        wrapped.empty = empty

        _lock = threading.Lock()
        _partial_ordered_dict = partial_ordered_dict(maxsize, default_value=_remove_old)
        _remove_old = functools.partial(_remove_old, lock=_lock)

        return wrapped

    return decorate

