def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freqs = {}
        hit_count = 0
        miss_count = 0

        def get_freq(key):
            return freqs.get(key, 0)

        def set_freq(key, freq):
            freqs[key] = freq

        def delete_by_freq(freq, duplicate_key=None):
            for key, _ in reversed(list(cache.items())):
                if freqs[key] == freq:
                    del cache[key]
                    del freqs[key]
                    if key != duplicate_key:  # never delete the duplicate
                        break

        def wrapper(*args, **kwargs):
            nonlocal hit_count, miss_count
            key = keyfunc(*args, **kwargs)
            if typed and type(key) not in _TYPED_KEYS:
                raise TypeError(f"The key {key} should be typed {type(key)}")
            try:
                value = cache[key]
                hit_count += 1
                freq = get_freq(key)
                set_freq(key, freq + 1)
                delete_by_freq(freq + 1)
                return value
            except KeyError:
                miss_count += 1
                if len(cache) >= maxsize:
                    delete_by_freq(0)
                value = func(*args, **kwargs)
                set_freq(key, 1)
                cache[key] = value
                return value

        return _update_wrapper(wrapper, func)
    return decorator
