def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    elif level < 0:
        level = float('inf')
    saved_d1 = {**d1}
    for k in d2:
        if k in d1:
            if level == 1:
                if d1[k] != d2[k]:
                    d1[k] = saved_d1[k]
            else:
                d1[k] = difference(d1[k], d2[k], level-1)
        else:
            d1[k] = saved_d1[k]
    return d1
