    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in ``last_applied_manifest`` if they are not yet present

    """
    for key, value in observer_schema.items():
        key_observer_schema = key.split('.')
        if len(key_observer_schema) > 1:
            response_value = value
            for key in key_observer_schema:
                if key in response:
                    response_value = response[key]
                else:
                    raise KeyError(f"Observed field '{key}' is not present in the Kubernetes response")
            last_applied_manifest[key] = response_value
        else:
            if key in response:
                last_applied_manifest[key] = response[key]
            else:
                raise KeyError(f"Observed field '{key}' is not present in the Kubernetes response")
