def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    manifest = app.spec.manifest
    default_observer_schema = {}
    for resource in manifest.resources:
        resource_schema = {}
        for field in resource.manifest.flatten():
            if field.name not in ["apiVersion", "kind", "metadata"]:
                field_type = field.type
                field_usage = field.usage
                if field_type == "integer":
                    resource_schema[field.name] = {
                        "type": "integer",
                        "usage": field_usage,
                    }
                elif field_type == "array":
                    resource_schema[field.name] = {
                        "type": "array",
                        "usage": field_usage,
                        "sub": [],
                    }
                elif field_type == "string":
                    resource_schema[field.name] = {
                        "type": "string",
                        "usage": field_usage,
                    }
                elif field_type in ["switch", "boolean"]:
                    resource_schema[field.name] = {
                        "type": "boolean",
                        "usage": field_usage,
                    }
                elif field_type in ["fixed", "enumeration"]:
                    resource_schema[field.name] = {
                        "type": "enumeration",
                        "usage": field_usage,
                        "values": field.values,
                    }
        default_observer_schema[resource.available_name] = {
            "type": "schema",
            "usage": "resource",
            "sub": resource_schema,
        }
    return default_observer_schema
```
Note that this method generates a fully-qualified observer schema for each Kubernetes resource in the manifest, so it can be used to validate and decode the individual resources of a given application.

