def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(path + "/0=*", "rb") as f:
            content = f.read()
            if content[:2] == b'\x89L':
                return "object"
            elif content[:3] == b'L\x0A\x0D':
                return "root"
            elif content[:1] == b'\x1F':
                return "file"
            else:
                return f"unknown error: {content}"
    except (IOError, TypeError):
        return "path cannot be found or is not a directory"
    except ValueError:
        return "unable to read file"
    except:
        return "unknown error"
