def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a datetime.datetime object.

    :param timestr: Any date/time string using the supported formats.
    :param default: The default datetime object, if this is a datetime object and not None, elements specified in timestr replace elements in the default object.
    :param ignoretz: If set True, time zones in parsed strings are ignored and a naive datetime.datetime object is returned.
    :param tzinfos: Additional time zone names / aliases which may be present in the string. This argument maps time zone names (and optionally offsets from those time zones) to time zones. This parameter can be a dictionary with timezone aliases mapping time zone names to time zones or a function taking two parameters (tzname and tzoffset) and returning a time zone.

    :return: Returns a datetime.datetime object or, if the fuzzy_with_tokens option is True, returns a tuple, the first element being a datetime.datetime object, the second a tuple containing the fuzzy tokens.
    """

    if default is not None and isinstance(default, datetime.datetime):
        fmt = default
    else:
        fmt = datetime.datetime.utcfromtimestamp(0)
    vals = {}
    for key, val in zip(['year', 'month', 'day', 'hour', 'minute', 'second'], [fmt.year, fmt.month, fmt.day, fmt.hour, fmt.minute, fmt.second]):
        vals[key] = val
    string_parts = timestr.split()
    for key, val in zip(['year', 'month', 'day', 'hour', 'minute', 'second'], string_parts):
        vals[key] = int(val)
        if key == 'second':
            # format 'yyyy-mm-dd hh:mm:ss'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
        elif key == 'minute':
            # format 'yyyy-mm-dd hh:mm:ssZ'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
            if val[-1] != 'Z':
                raise ValueError("Invalid format")
        elif key == 'hour':
            # format 'yyyy-mm-dd hh:mm:ss+zz:zz' or 'yyyy-mm-dd hh:mm:ss-zz:zz'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count('+') != 1 and val.count('-') != 1:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
        elif key == 'day':
            # format 'yyyy-mm-dd hh:mm:ssZ or yyyy-mm-dd hh:mm:ss+zz:zz'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count('+') != 0 and val.count('-') != 0:
                raise ValueError("Invalid format")
            if val.count(':') != 0:
                raise ValueError("Invalid format")
        elif key == 'month':
            # format 'yyyy-mm-dd hh:mm:ssZ'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
            if val[-1] != 'Z':
                raise ValueError("Invalid format")
        elif key == 'year':
            # format 'yyyy-mm-dd hh:mm:ssZ'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
            if val[-1] != 'Z':
                raise ValueError("Invalid format")

    # check for time zone
    if '+' in vals['second']:
        # parse 'yyyy-mm-dd hh:mm:ss+zz:zz'
        if len(vals['second']) != 25:
            raise ValueError("Invalid format")
        vals['second'] = vals['second'][:-6]
        timezone = 'GMT' + vals['second'][11:]
        vals['second'] = vals['second'][:10]
    elif '-' in vals['second']:
        # parse 'yyyy-mm-dd hh:mm:ss+zz:zz'
        if len(vals['second']) != 25:
            raise ValueError("Invalid format")
        vals['second'] = vals['second'][:-6]
        timezone = 'GMT' + vals['second'][11:]
        vals['second'] = vals['second'][:10]
    elif vals['second'][-1] == 'Z':
        # parse 'yyyy-mm-dd hh:mm:ss+zz:zz'
        if len(vals['second']) != 22:
            raise ValueError("Invalid format")
        timezone = 'UTC'
        vals['second'] = vals['second'][:20]
    else:
        raise ValueError("Invalid format")

    if ignoretz is True:
        vals['second'] = datetime.datetime.utcfromtimestamp(0).replace(year=vals['year'], month=vals['month'], day=vals['day'], hour=vals['hour'], minute=vals['minute'], second=vals['second']).replace(tzinfo=timezone)
    elif tzinfos is not None:
        if isinstance(tzinfos, dict):
            if timezone in tzinfos.keys():
                timezone = tzinfos[timezone]
                vals['second'] = datetime.datetime.utcfromtimestamp(0).replace(year=vals['year'], month=vals['month'], day=vals['day'], hour=vals['hour'], minute=vals['minute'], second=vals['second']).replace(tzinfo=timezone)
        elif callable(tzinfos):
            tzinfos(timezone, vals['hour'])
        else:
            raise ValueError('tzinfos must be a dictionary or a function')

    return vals['second']
