def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    req = urllib2.Request(url, headers={'Host': url.netloc})
    resp = None
    try:
        resp = urllib2.urlopen(req)
        return resp.info().get('content-type', None)
    except HTTPError as e:
        if e.code != 200:
            return None
        else:
            raise e
    finally:
        if resp is not None:
            resp.close()
