def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_doc = json.loads(document)
        return parse_diaspora_webfinger(json_doc)
    except json.JSONDecodeError:
        try:
            return parse_diaspora_webfinger_xrd(document)
        except Exception:
            return None

def parse_diaspora_webfinger_xrd(document: str) -> dict:
    """
    Parse an XRD document and return a Diaspora webfinger representation.

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    root = ElementTree.fromstring(document)
    hostmap = {}
    for service in root.findall(".//{http://www.w3.org/2005/Atom}Service"):
        properties = service.findall(".//{http://www.w3.org/2005/Atom}app:Workspace")[0].attrib
        service_type = properties["{http://www.w3.org/2005/Atom}term"]
        if service_type == "http://joindiaspora.com/ns/services/streaming":
            hostmap[service.findall(".//{http://www.w3.org/2005/Atom}app:publishable")[0].attrib["app:href"]] = service.findall(".//{http://www.w3.org/2005/Atom}app:uri")[0].attrib["app:handle"]
    return hostmap
