def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend `vars_dict` with `extra-vars`."""
    if not vars_dict:
        raise ValueError("Unable to merge: vars_dict is not a valid dictionary")
    if not isinstance(extra_vars, list):
        raise ValueError("Unable to merge: extra_vars is not a valid list")

    if extra_vars is None:
        return vars_dict

    for extra_var in extra_vars:
